using CapitalPos.Application.Inventario; using CapitalPos.Domain; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.DependencyInjection;
namespace CapitalPos.Infrastructure.Persistence.Repositories;
public sealed class EfMovimientoInventarioRepository(IServiceProvider services) : IMovimientoInventarioRepository { private CapitalPosDbContext? Db => services.GetService<CapitalPosDbContext>(); public async Task AgregarAsync(MovimientoInventario m,CancellationToken c=default) { if (Db is not null) await Db.AddAsync(m,c); } public async Task<IReadOnlyCollection<MovimientoInventario>> ListarPorEmpresaAsync(Guid e,CancellationToken c=default)=>Db is null ? [] : await Db.Set<MovimientoInventario>().AsNoTracking().Where(x=>x.EmpresaId==e).OrderByDescending(x=>x.FechaCreacion).ToListAsync(c); }
